where 1=1

		and crmp_llave = #{key}


		and crmp_estado = #{state}


		and crmp_catalogo = #{catalog}


		and crmp_cuenta = #{account}


		and nrmp_nivel = #{level}


		and drmp_fechainicio = #{startDate}


		and drmp_fechafin = #{endDate}


		and crmp_periodo = #{period}


		and nrmp_ano = #{year}


		and nrmp_mes = #{month}


		and nrmp_dia = #{day}


		and nrmp_hora = #{hour}


		and nrmp_minuto = #{minute}


		and nrmp_cantidad = #{quantity}


		and nrmp_promedio = #{average}


		and mrmp_saldoanterior = #{lastBalance}


		and mrmp_saldosiguiente = #{nextBalance}


		and mrmp_positivo = #{positive}


		and mrmp_negativo = #{negative}


		and mrmp_valor = #{value}


		and crmp_tipo = #{type}
